// npm/scripts/install.js — the npm launcher's postinstall downloader.
//
// rm-211 hardening (this cycle's arms): every download hop is pinned
// to https + the github release-asset hosts, every download is byte
// capped, and the binary checksum is verified against a
// package-pinned map (scripts/pinned-checksums.json, generated by the
// release workflow and shipped inside this npm package) — the npm
// registry's own tarball integrity transitively pins the release
// binary hash, an independent channel from the github download. The
// release-channel .sha256 is still fetched and cross-checked; a
// disagreement between the two channels fails the install.

const { createHash } = require("node:crypto");
const {
	createWriteStream,
	existsSync,
	readFileSync,
	renameSync,
	rmSync,
} = require("node:fs");
const https = require("node:https");
const { join } = require("node:path");
const { pipeline } = require("node:stream");
const { Transform } = require("node:stream");

const { verifyRuntime } = require(join(__dirname, "verify-runtime.js"));

const PACKAGE_NAME = "@zack78/agenttrace";
// The workflow stamps npm/package.json before packing; the value here
// is only a fallback for direct repo checkouts.
const PACKAGE_VERSION =
	process.env.AGENTTRACE_RELEASE_VERSION || require("../package.json").version;
const REPO = "zack78/agenttrace";

// Only these hosts may ever serve the binary: the release page and
// GitHub's release-asset CDN. A redirect anywhere else (or any
// non-https hop) fails the install instead of following it.
const REDIRECT_ALLOWLIST = new Set([
	"github.com",
	"objects.githubusercontent.com",
	"release-assets.githubusercontent.com",
]);
const MAX_REDIRECTS = 5;
// rm-211: the release binaries are tens of MiB; 4 GiB is the
// documented ceiling so a hostile or broken feed can never balloon
// unbounded.
const MAX_DOWNLOAD_BYTES = 4 * 1024 * 1024 * 1024;
const PINNED_CHECKSUMS_PATH = join(__dirname, "pinned-checksums.json");

function fail(message) {
	throw new Error(message);
}

function httpsGet(url, callback) {
	return https.get(url, callback);
}

function assertPinnedUrl(rawUrl, hop = 0) {
	const url = new URL(rawUrl);
	if (url.protocol !== "https:") {
		fail(`refusing to download over ${url.protocol} (https only): ${rawUrl}`);
	}
	if (!REDIRECT_ALLOWLIST.has(url.hostname)) {
		fail(
			`download host is not pinned: ${url.hostname} (allowed: ${[...REDIRECT_ALLOWLIST]
				.sort()
				.join(", ")}) — ${rawUrl}`,
		);
	}
	if (hop > MAX_REDIRECTS) {
		fail(`too many download redirects (more than ${MAX_REDIRECTS}): ${rawUrl}`);
	}
	return url;
}

function byteCapTransform(maxBytes, label) {
	let received = 0;
	return new Transform({
		transform(chunk, encoding, callback) {
			received += chunk.length;
			if (received > maxBytes) {
				callback(
					new Error(
						`download of ${label} exceeded the byte cap (${maxBytes} bytes) after ${received} bytes`,
					),
				);
				return;
			}
			callback(null, chunk);
		},
	});
}

function download(rawUrl, destination, { hop = 0, maxBytes = MAX_DOWNLOAD_BYTES, getter = httpsGet } = {}) {
	return new Promise((resolve, reject) => {
		let url;
		try {
			url = assertPinnedUrl(rawUrl, hop);
		} catch (error) {
			reject(error);
			return;
		}
		const request = getter(url, (response) => {
			const status = response.statusCode || 0;
			if (status >= 300 && status < 400) {
				const location = response.headers.location;
				response.resume();
				if (!location) {
					reject(new Error(`download of ${url} got ${status} without a location header`));
					return;
				}
				resolve(download(new URL(location, url), destination, { hop: hop + 1, maxBytes, getter }));
				return;
			}
			if (status !== 200) {
				response.resume();
				reject(new Error(`download of ${url} failed with status ${status}`));
				return;
			}
			const declared = Number(response.headers["content-length"]);
			if (Number.isFinite(declared) && declared > maxBytes) {
				response.destroy();
				reject(
					new Error(
						`download of ${url} declares ${declared} bytes, over the ${maxBytes}-byte cap`,
					),
				);
				return;
			}
			pipeline(
				response,
				byteCapTransform(maxBytes, url.pathname),
				createWriteStream(destination),
				(error) => {
					if (error) {
						rmSync(destination, { force: true });
						reject(error);
						return;
					}
					resolve();
				},
			);
		});
		request.on("error", reject);
	});
}

function readPinnedChecksums(path = PINNED_CHECKSUMS_PATH) {
	if (!existsSync(path)) {
		return null;
	}
	let parsed;
	try {
		parsed = JSON.parse(readFileSync(path, "utf8"));
	} catch (error) {
		fail(`pinned checksum file is not valid JSON (${path}: ${error.message})`);
	}
	if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
		fail(`pinned checksum file must map asset names to sha256 digests (${path})`);
	}
	for (const [name, digest] of Object.entries(parsed)) {
		if (!/^[0-9a-f]{64}$/i.test(String(digest))) {
			fail(`pinned checksum for ${name} is not a sha256 hex digest (${path})`);
		}
	}
	return parsed;
}

function reconcileChecksums(asset, pinned, channel) {
	if (pinned !== null && channel !== null && pinned !== channel) {
		fail(
			`checksum channels disagree for ${asset}: package-pinned ${pinned} vs release-channel ${channel}`,
		);
	}
	return pinned ?? channel;
}

function getAssetName() {
	const platform = { darwin: "darwin", linux: "linux", win32: "windows" }[
		process.platform
	] ?? fail(`unsupported platform: ${process.platform}`);
	const arch = { x64: "amd64", arm64: "arm64" }[process.arch] ?? fail(
		`unsupported architecture: ${process.arch}`,
	);
	const executable = process.platform === "win32" ? ".exe" : "";
	return `agenttrace-${platform}-${arch}${executable}`;
}

function getBinaryPath() {
	const executable = process.platform === "win32" ? "agenttrace.exe" : "agenttrace";
	return join(__dirname, "..", "bin", executable);
}

async function main() {
	const asset = getAssetName();
	const releaseUrl = `https://github.com/${REPO}/releases/download/v${PACKAGE_VERSION}/${asset}`;
	const checksumUrl = `${releaseUrl}.sha256`;

	const temporaryBinary = `${getBinaryPath()}.download`;
	const temporaryChecksum = `${getBinaryPath()}.sha256`;
	const pinnedChecksums = readPinnedChecksums();
	const pinned =
		pinnedChecksums !== null && Object.prototype.hasOwnProperty.call(pinnedChecksums, asset)
			? pinnedChecksums[asset]
			: null;
	if (pinned === null) {
		console.warn(
			`agenttrace: no package-pinned checksum for ${asset}; the GitHub release channel is the only integrity source`,
		);
	}

	try {
		const binaryDownload = download(releaseUrl, temporaryBinary);
		const checksumDownload = pinned
			? download(checksumUrl, temporaryChecksum).then(
					() => readFileSync(temporaryChecksum, "utf8").trim().split(/\s+/)[0],
					() => null, // the package pin is the independent channel
				)
			: download(checksumUrl, temporaryChecksum).then(
					() => readFileSync(temporaryChecksum, "utf8").trim().split(/\s+/)[0],
				);
		const [, channelChecksum] = await Promise.all([binaryDownload, checksumDownload]);

		const binary = readFileSync(temporaryBinary);
		const actual = createHash("sha256").update(binary).digest("hex");
		const expected = reconcileChecksums(asset, pinned, channelChecksum);
		if (expected !== actual) {
			fail(`checksum mismatch for ${asset}: expected ${expected}, got ${actual}`);
		}

		const binaryPath = getBinaryPath();
		renameSync(temporaryBinary, binaryPath);
		const result = verifyRuntime(binaryPath);
		if (!result.ok) {
			fail(
				`the downloaded agenttrace binary did not run on this machine: ${result.stderrTail}`,
			);
		}
		console.log(`Installed ${PACKAGE_NAME} ${PACKAGE_VERSION} (${result.version}).`);
	} finally {
		rmSync(temporaryBinary, { force: true });
		rmSync(temporaryChecksum, { force: true });
	}
}

if (require.main === module) {
	main().catch((error) => {
		console.error(`agenttrace installation failed: ${error.message}`);
		process.exitCode = 1;
	});
}

module.exports = {
	MAX_DOWNLOAD_BYTES,
	MAX_REDIRECTS,
	REDIRECT_ALLOWLIST,
	assertPinnedUrl,
	download,
	readPinnedChecksums,
	reconcileChecksums,
};
